-- Refresh only the untouched legacy intake message; preserve customized templates.
ALTER TABLE public.business_config
  ALTER COLUMN tracking_intake_template SET DEFAULT E'Hola, {{cliente_nombre}}.\n\nHemos recibido y registrado tu equipo en {{negocio_nombre}}.\n\nCódigo del ingreso: {{codigo_ingreso}}\nFecha de ingreso: {{fecha_ingreso}}\nEquipo: {{dispositivo}}\nMotivo del ingreso o servicio solicitado: {{motivo_ingreso}}\nEstado actual: {{estado_actual}}\n\nPuedes consultar en cualquier momento el estado de la reparación, los avances y las fotografías publicadas desde el siguiente enlace:\n\n{{enlace_seguimiento}}\n\nConserva este enlace para futuras consultas.\n\nSi tienes alguna inquietud, puedes comunicarte con nosotros.';

UPDATE public.business_config
SET tracking_intake_template = E'Hola, {{cliente_nombre}}.\n\nHemos recibido y registrado tu equipo en {{negocio_nombre}}.\n\nCódigo del ingreso: {{codigo_ingreso}}\nFecha de ingreso: {{fecha_ingreso}}\nEquipo: {{dispositivo}}\nMotivo del ingreso o servicio solicitado: {{motivo_ingreso}}\nEstado actual: {{estado_actual}}\n\nPuedes consultar en cualquier momento el estado de la reparación, los avances y las fotografías publicadas desde el siguiente enlace:\n\n{{enlace_seguimiento}}\n\nConserva este enlace para futuras consultas.\n\nSi tienes alguna inquietud, puedes comunicarte con nosotros.'
WHERE tracking_intake_template = E'Hola, {{cliente_nombre}}.\n\nHemos registrado el ingreso de tu equipo en {{negocio_nombre}}.\n\nCódigo del ingreso: {{codigo_ingreso}}\nDispositivo: {{dispositivo}}\nMotivo del ingreso o servicio solicitado: {{servicio_solicitado}}\nEstado actual: {{estado_actual}}\n\nPuedes consultar en cualquier momento el estado de la reparación, sus avances y las fotografías autorizadas desde el siguiente enlace:\n\n{{enlace_seguimiento}}\n\nConserva este enlace para futuras consultas.';
